import React, { useState, useEffect, useRef } from "react";

import { StudioProApi } from "@mendix/extensions-api";
import { Link } from "@mendix/ide-ui-components/link/Link";

import { Model } from "../../../types/model/model";
import { MxCloudGenAIModelFields } from "../../../types/model/mxCloudGenAIModel";
import {
    applyKeyImportHelperChange,
    handleImportKeyFromPortal,
    handleTestConnection,
    handleValidateKey,
} from "./mxCloudGenAIHandlers";

import { anthropicIconBase64 } from "../../../icons/modelIcons";
import { SuccessBanner } from "../../components/Banner";
import TextAreaWithButton from "../../components/TextAreaWithButton";
import TextInputLabeled from "../../components/TextInputLabeled";
import GroupBox from "../../components/GroupBox";
import { DivFlexColumn, DivFlexRow, StyledLabel } from "../../components/elements/formelements";
import ButtonWithLabel from "../../components/ButtonWithLabel";

interface MxCloudGenAIProps {
    studioPro: StudioProApi;
    model: Model;
    setModel: React.Dispatch<React.SetStateAction<Model>>;
    updateStudioProDocument: (model: Model) => Promise<void>;
}

const MxCloudGenAI: React.FC<MxCloudGenAIProps> = ({ studioPro, model, setModel, updateStudioProDocument }) => {
    const [showConnectionOK, setShowConnectionOK] = useState(false);
    const providerFields = model.providerFields as MxCloudGenAIModelFields;

    const emptyOnChange = () => {};

    // Ref for debouncing document updates
    const keyImportHelperTimeout = useRef<ReturnType<typeof setTimeout> | null>(null);

    useEffect(() => {
        if (showConnectionOK) {
            const timer = setTimeout(() => {
                setShowConnectionOK(false);
            }, 5000);
            return () => clearTimeout(timer);
        }
    }, [showConnectionOK]);

    // Debounced handler for keyImportHelper
    const onKeyImportHelperChange = (value: string) => {
        const updatedKeyHelper: Model = {
            ...model,
            providerFields: { ...model.providerFields, keyImportHelper: value },
        };
        setModel(updatedKeyHelper);
        if (keyImportHelperTimeout.current) {
            clearTimeout(keyImportHelperTimeout.current);
        }
        keyImportHelperTimeout.current = setTimeout(() => {
            const updatedModel: Model = applyKeyImportHelperChange(model, value, updateStudioProDocument);
            setModel(updatedModel);
        }, 300);
    };

    const importKeyFromPortal = async () => {
        handleImportKeyFromPortal(studioPro, model, setModel, updateStudioProDocument)();
        setShowConnectionOK(false);
    };

    const testConnection = async () => {
        setShowConnectionOK(false);
        const isSuccess: boolean = await handleTestConnection(studioPro, model, setModel, updateStudioProDocument);
        setShowConnectionOK(isSuccess);
    };

    const validateKey = () => {
        return handleValidateKey(model);
    };

    const onBannerClose = () => {
        setShowConnectionOK(false);
    };

    return (
        <GroupBox label="Resource">
            <TextAreaWithButton
                label="Model key"
                ariaLabel="Model key"
                value={providerFields.keyImportHelper || ""}
                onChange={onKeyImportHelperChange}
                buttonCaption="Import"
                onClick={importKeyFromPortal}
                validate={validateKey}
                description={!providerFields.key ? "Please enter your key from the portal." : undefined}
                buttonDisabled={providerFields.keyImportHelper === ""}
            />
            {!providerFields.key && (
                <DivFlexRow>
                    <DivFlexColumn>
                        <StyledLabel></StyledLabel>
                    </DivFlexColumn>
                    <DivFlexColumn fullWidth>
                        <Link href="https://genai.home.mendix.com/p/resources" target="_blank">
                            Create a key in the portal
                        </Link>
                    </DivFlexColumn>
                </DivFlexRow>
            )}
            {providerFields.key && (
                <>
                    <TextInputLabeled
                        label="Resource"
                        ariaLabel="Resource name"
                        value={providerFields.resourceName}
                        onChange={emptyOnChange}
                        readOnly={true}
                    />
                    <TextInputLabeled
                        label="Key"
                        ariaLabel="Key name"
                        value={providerFields.keyName}
                        onChange={emptyOnChange}
                        readOnly={true}
                    />
                    <TextInputLabeled
                        label="Model"
                        ariaLabel="Model name"
                        value={model.displayName}
                        icon={
                            model.displayName && model.displayName.toLocaleLowerCase().includes("anthropic")
                                ? anthropicIconBase64
                                : undefined
                        }
                        onChange={emptyOnChange}
                        readOnly={true}
                    />
                    <TextInputLabeled
                        label="Model ID"
                        ariaLabel="Model ID"
                        value={model.name}
                        onChange={emptyOnChange}
                        readOnly={true}
                    />
                    <TextInputLabeled
                        label="Environment"
                        ariaLabel="Environment"
                        value={providerFields.environment}
                        onChange={emptyOnChange}
                        readOnly={true}
                    />
                    <DivFlexRow>
                        <DivFlexColumn>
                            <StyledLabel></StyledLabel>
                        </DivFlexColumn>
                        <DivFlexColumn fullWidth>
                            <Link href={providerFields.deepLinkURL} target="_blank">
                                View resource in the portal
                            </Link>
                        </DivFlexColumn>
                    </DivFlexRow>
                    <ButtonWithLabel label="Connection" buttonCaption="Test" onPress={testConnection} />
                    {showConnectionOK && <SuccessBanner onClose={onBannerClose}>Connection successful.</SuccessBanner>}
                </>
            )}
        </GroupBox>
    );
};

export default MxCloudGenAI;
